package com.gamehub.admin;import com.gamehub.category.CategoryService;import com.gamehub.category.dto.CategoryRequest;import com.gamehub.category.entity.Category;import com.gamehub.common.ApiResponse;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api/v1/admin/categories") public class AdminCategoryController {private final CategoryService service;public AdminCategoryController(CategoryService service){this.service=service;}@GetMapping public ApiResponse<List<Category>>list(){return ApiResponse.ok(service.all());}@PostMapping public ApiResponse<Category>create(@Valid @RequestBody CategoryRequest r){return ApiResponse.ok(service.save(null,r));}@PutMapping("/{id}")public ApiResponse<Category>update(@PathVariable Long id,@Valid @RequestBody CategoryRequest r){return ApiResponse.ok(service.save(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void>delete(@PathVariable Long id){service.delete(id);return ApiResponse.ok();}}
